const galleryModal=document.querySelector('#gallery-modal');const galleryModalMedia=document.querySelector('#gallery-modal-media');const galleryModalTitle=document.querySelector('#gallery-modal-title');const galleryModalDescription=document.querySelector('#gallery-modal-description');const closeGalleryModal=()=>{galleryModal.classList.remove('open');galleryModal.setAttribute('aria-hidden','true');galleryModalMedia.replaceChildren();document.body.style.overflow=''};const videoEmbed=(source)=>{const youtube=source.match(/(?:youtube\.com\/(?:watch\?.*v=|shorts\/|embed\/)|youtu\.be\/)([\w-]{11})/);const vimeo=source.match(/vimeo\.com\/(?:video\/)?(\d+)/);const drive=source.match(/drive\.google\.com\/file\/d\/([^/]+)/);if(youtube)return `https://www.youtube.com/embed/${youtube[1]}?autoplay=1&rel=0`;if(vimeo)return `https://player.vimeo.com/video/${vimeo[1]}?autoplay=1`;if(drive)return `https://drive.google.com/file/d/${drive[1]}/preview`;return null};document.querySelectorAll('.gallery-card').forEach((card)=>card.addEventListener('click',()=>{let media;if(card.dataset.galleryType==='video'){const embed=videoEmbed(card.dataset.gallerySrc);media=embed?document.createElement('iframe'):document.createElement('video');media.src=embed||card.dataset.gallerySrc;if(embed){media.title=card.dataset.galleryTitle;media.allow='autoplay; fullscreen; picture-in-picture';media.allowFullscreen=true}else{media.controls=true;media.autoplay=true;media.playsInline=true}}else{media=document.createElement('img');media.src=card.dataset.gallerySrc;media.alt=card.dataset.galleryTitle}galleryModalMedia.replaceChildren(media);galleryModalTitle.textContent=card.dataset.galleryTitle;galleryModalDescription.textContent=card.dataset.galleryDescription;galleryModal.classList.add('open');galleryModal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}));document.querySelector('.gallery-modal-close').addEventListener('click',closeGalleryModal);galleryModal.addEventListener('click',(event)=>{if(event.target===galleryModal)closeGalleryModal()});document.addEventListener('keydown',(event)=>{if(event.key==='Escape')closeGalleryModal()});

